'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { migrateUsersToRolesArray } from '@/lib/firebase/firestore';
import { useAuth } from '@/contexts/AuthContext';
import { hasAnyRole } from '@/lib/firebase/auth';
import { Loader2, CheckCircle, XCircle } from 'lucide-react';

export default function MigratePage() {
  const { userData } = useAuth();
  const [migrating, setMigrating] = useState(false);
  const [result, setResult] = useState<{ migrated: number; errors: number } | null>(null);

  // Only allow admins to access this page
  if (!userData || !hasAnyRole(userData, ['admin', 'super admin'])) {
    return (
      <div className='flex items-center justify-center min-h-[60vh]'>
        <Card className='w-full max-w-md'>
          <CardHeader>
            <CardTitle>Access Denied</CardTitle>
            <CardDescription>You must be an admin to access this page.</CardDescription>
          </CardHeader>
        </Card>
      </div>
    );
  }

  const handleMigrate = async () => {
    setMigrating(true);
    setResult(null);
    try {
      const result = await migrateUsersToRolesArray();
      setResult(result);
    } catch (error) {
      console.error('Migration error:', error);
      setResult({ migrated: 0, errors: 1 });
    } finally {
      setMigrating(false);
    }
  };

  return (
    <div className='container mx-auto p-6 max-w-2xl'>
      <Card>
        <CardHeader>
          <CardTitle>Migrate Users to Roles Array</CardTitle>
          <CardDescription>
            This will convert all existing users from single role to roles array format.
            All admins will automatically get the 'user' role as well.
          </CardDescription>
        </CardHeader>
        <CardContent className='space-y-4'>
          <Button
            onClick={handleMigrate}
            disabled={migrating}
            className='w-full'
          >
            {migrating ? (
              <>
                <Loader2 className='mr-2 h-4 w-4 animate-spin' />
                Migrating...
              </>
            ) : (
              'Run Migration'
            )}
          </Button>

          {result && (
            <div className='space-y-2 p-4 border rounded-lg'>
              <div className='flex items-center gap-2'>
                {result.errors === 0 ? (
                  <CheckCircle className='h-5 w-5 text-green-500' />
                ) : (
                  <XCircle className='h-5 w-5 text-red-500' />
                )}
                <span className='font-semibold'>
                  Migration {result.errors === 0 ? 'Completed' : 'Finished with Errors'}
                </span>
              </div>
              <div className='text-sm text-muted-foreground space-y-1'>
                <p>Users migrated: {result.migrated}</p>
                <p>Errors: {result.errors}</p>
              </div>
            </div>
          )}

          <div className='text-sm text-muted-foreground p-4 bg-muted rounded-lg'>
            <p className='font-semibold mb-2'>What this does:</p>
            <ul className='list-disc list-inside space-y-1'>
              <li>Converts single role field to roles array</li>
              <li>Adds 'user' role to all admins and photographers</li>
              <li>Preserves existing roles</li>
              <li>Updates all user documents in Firestore</li>
            </ul>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

